from collections import Counter


def min_window(s, t):
    need = Counter(t)
    best = ""
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            window = s[i:j + 1]
            window_count = Counter(window)                      # recount this window's characters from scratch
            if all(window_count[ch] >= need[ch] for ch in need):
                if best == "" or len(window) < len(best):
                    best = window
    return best


if __name__ == "__main__":
    s = "ADOBECODEBANC"
    t = "ABC"
    print(min_window(s, t))

