import java.util.*;

public class Main {
    String minWindow(String s, String t) {
        Map<Character, Integer> need = new HashMap<>();
        for (char ch : t.toCharArray()) need.merge(ch, 1, Integer::sum);
        String best = "";
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                Map<Character, Integer> windowCount = new HashMap<>();
                for (int k = i; k <= j; k++) {                          // recount this window's characters from scratch
                    windowCount.merge(s.charAt(k), 1, Integer::sum);
                }
                boolean satisfies = true;
                for (char ch : need.keySet()) {
                    if (windowCount.getOrDefault(ch, 0) < need.get(ch)) { satisfies = false; break; }
                }
                if (satisfies && (best.isEmpty() || j - i + 1 < best.length())) {
                    best = s.substring(i, j + 1);
                }
            }
        }
        return best;
    }

    public static void main(String[] args) {
        String s = "ADOBECODEBANC";
        String t = "ABC";
        Main solution = new Main();
        System.out.println(solution.minWindow(s, t));
    }
}

