import java.util.*;

public class Main {
    String minWindow(String s, String t) {
        Map<Character, Integer> need = new HashMap<>();
        for (char ch : t.toCharArray()) need.merge(ch, 1, Integer::sum);
        int missing = need.size();                                  // how many distinct characters are not yet satisfied
        Map<Character, Integer> windowCount = new HashMap<>();
        int left = 0, bestLeft = 0, bestRight = -1;
        for (int right = 0; right < s.length(); right++) {
            char ch = s.charAt(right);
            windowCount.merge(ch, 1, Integer::sum);
            if (need.containsKey(ch) && windowCount.get(ch).intValue() == need.get(ch).intValue()) {
                missing--;                                                // this character's requirement is satisfied
            }
            while (missing == 0) {                                     // window is currently valid, try to shrink it
                if (bestRight == -1 || right - left < bestRight - bestLeft) {
                    bestLeft = left; bestRight = right;
                }
                char leftCh = s.charAt(left);
                windowCount.put(leftCh, windowCount.get(leftCh) - 1);
                if (need.containsKey(leftCh) && windowCount.get(leftCh) < need.get(leftCh)) {
                    missing++;                                                // shrinking broke a requirement
                }
                left++;
            }
        }
        return bestRight == -1 ? "" : s.substring(bestLeft, bestRight + 1);
    }

    public static void main(String[] args) {
        String s = "ADOBECODEBANC";
        String t = "ABC";
        Main solution = new Main();
        System.out.println(solution.minWindow(s, t));
    }
}

