string minWindow(string s, string t) {
    unordered_map<char, int> need;
    for (char ch : t) need[ch]++;
    int missing = (int)need.size();                              // how many distinct characters are not yet satisfied
    unordered_map<char, int> windowCount;
    int left = 0, bestLeft = 0, bestRight = -1;
    for (int right = 0; right < (int)s.size(); right++) {
        char ch = s[right];
        windowCount[ch]++;
        if (need.count(ch) && windowCount[ch] == need[ch]) {
            missing--;                                                  // this character's requirement is satisfied
        }
        while (missing == 0) {                                        // window is currently valid, try to shrink it
            if (bestRight == -1 || right - left < bestRight - bestLeft) {
                bestLeft = left; bestRight = right;
            }
            char leftCh = s[left];
            windowCount[leftCh]--;
            if (need.count(leftCh) && windowCount[leftCh] < need[leftCh]) {
                missing++;                                                  // shrinking broke a requirement
            }
            left++;
        }
    }
    return bestRight == -1 ? "" : s.substr(bestLeft, bestRight - bestLeft + 1);
}

